#include <stdio.h>

#define MAXN 45

int main(void)
{
    int n, i;
    int f[MAXN];
    int odd = 0, even = 0;

    scanf("%d", &n);
    if (n >= 1) {
        f[1] = 1;
    }
    if (n >= 2) {
        f[2] = 2;
    }
    for (i = 3; i <= n; i++) {
        f[i] = f[i - 1] + f[i - 2];
    }
    for (i = 1; i <= n; i++) {
        if (f[i] % 2 == 0) {
            even++;
        } else {
            odd++;
        }
    }
    printf("方案数 %d\n", f[n]);
    printf("奇数 %d 项\n", odd);
    printf("偶数 %d 项\n", even);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n, i, s, idx;
    int cnt[11] = {0};
    int pass;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &s);
        idx = s / 10;
        cnt[idx]++;
    }
    printf("90-100: %d\n", cnt[9] + cnt[10]);
    printf("80-89: %d\n", cnt[8]);
    printf("70-79: %d\n", cnt[7]);
    printf("60-69: %d\n", cnt[6]);
    printf("0-59: %d\n", cnt[0] + cnt[1] + cnt[2] + cnt[3] + cnt[4] + cnt[5]);
    pass = n - (cnt[0] + cnt[1] + cnt[2] + cnt[3] + cnt[4] + cnt[5]);
    printf("及格率: %.1f%%\n", 100.0 * pass / n);
    return 0;
}

#include <stdio.h>

#define MAXV 1005

int main(void)
{
    int n, i, x;
    int first[MAXV], last[MAXV];
    int best = -1, bestVal = -1;

    for (i = 0; i < MAXV; i++) {
        first[i] = -1;
        last[i] = -1;
    }
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x);
        if (first[x] == -1) {
            first[x] = i;
        }
        last[x] = i;
    }
    for (x = 1; x < MAXV; x++) {
        if (first[x] != -1 && last[x] > first[x]) {
            int d = last[x] - first[x];
            if (d > best) {
                best = d;
                bestVal = x;
            }
        }
    }
    if (bestVal == -1) {
        printf("No repeat\n");
    } else {
        printf("最大跨度 %d\n", best);
        printf("该数值 %d\n", bestVal);
    }
    return 0;
}

#include <stdio.h>

#define MAXN 25

int main(void)
{
    int n, s, r, c, num = 1;
    int rMin, rMax;
    int a[MAXN][MAXN];

    scanf("%d", &n);
    for (s = 2; s <= 2 * n; s++) {
        rMin = s - n;
        if (rMin < 1) {
            rMin = 1;
        }
        rMax = s - 1;
        if (rMax > n) {
            rMax = n;
        }
        if (s % 2 == 0) {
            for (r = rMin; r <= rMax; r++) {
                c = s - r;
                a[r][c] = num++;
            }
        } else {
            for (r = rMax; r >= rMin; r--) {
                c = s - r;
                a[r][c] = num++;
            }
        }
    }
    for (r = 1; r <= n; r++) {
        for (c = 1; c <= n; c++) {
            if (c > 1) {
                printf(" ");
            }
            printf("%d", a[r][c]);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

#define MAXN 25

int main(void)
{
    int n, i, j, r, c;
    int a[MAXN][MAXN];
    int sr[MAXN * 2], sc[MAXN * 2];
    int m = 0;
    long long best = -1;
    int bestR = 1, bestC = 1;

    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            scanf("%d", &a[i][j]);
        }
    }
    for (i = 1; i <= n; i++) {
        sr[m] = i;
        sc[m] = 1;
        m++;
    }
    for (j = 2; j <= n; j++) {
        sr[m] = 1;
        sc[m] = j;
        m++;
    }
    for (i = 0; i < m; i++) {
        long long sum = 0;
        r = sr[i];
        c = sc[i];
        while (r <= n && c <= n) {
            sum += a[r][c];
            r++;
            c++;
        }
        if (sum > best) {
            best = sum;
            bestR = sr[i];
            bestC = sc[i];
        }
    }
    printf("最大斜线和 %lld\n", best);
    printf("起点为第 %d 行第 %d 列\n", bestR, bestC);
    return 0;
}

#include <stdio.h>

#define MAXN 25

int main(void)
{
    int n, i, j;
    int a[MAXN][MAXN] = {{0}};
    long long dp[MAXN][MAXN] = {{0}};
    int cj;

    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= i; j++) {
            scanf("%d", &a[i][j]);
        }
    }
    for (j = 1; j <= n; j++) {
        dp[n][j] = a[n][j];
    }
    for (i = n - 1; i >= 1; i--) {
        for (j = 1; j <= i; j++) {
            long long below = dp[i + 1][j];
            if (dp[i + 1][j + 1] > below) {
                below = dp[i + 1][j + 1];
            }
            dp[i][j] = a[i][j] + below;
        }
    }
    printf("最大和 %lld\n", dp[1][1]);
    printf("路径:");
    cj = 1;
    for (i = 1; i <= n; i++) {
        printf(" %d", a[i][cj]);
        if (i < n && dp[i + 1][cj + 1] > dp[i + 1][cj]) {
            cj++;
        }
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

#define MAXL 1005

int main(void)
{
    char s[MAXL];
    int last[26];
    int i, left = 0, bestLen = 0, bestStart = 0;

    if (fgets(s, sizeof(s), stdin) == NULL) {
        return 0;
    }
    for (i = 0; i < 26; i++) {
        last[i] = -1;
    }
    for (i = 0; s[i] != '\0' && s[i] != '\n' && s[i] != '\r'; i++) {
        int c = s[i] - 'a';
        if (last[c] >= left) {
            left = last[c] + 1;
        }
        last[c] = i;
        if (i - left + 1 > bestLen) {
            bestLen = i - left + 1;
            bestStart = left;
        }
    }
    printf("longest: %d\n", bestLen);
    printf("segment: %.*s\n", bestLen, s + bestStart);
    return 0;
}

#include <stdio.h>

#define MAXN 1005

int main(void)
{
    int n, i, j, t;
    int a[MAXN], idx[MAXN];
    long long total = 0;

    scanf("%d", &n);
    for (i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        idx[i] = i;
    }
    for (i = 1; i < n; i++) {
        for (j = 1; j <= n - i; j++) {
            if (a[idx[j]] > a[idx[j + 1]] ||
                (a[idx[j]] == a[idx[j + 1]] && idx[j] > idx[j + 1])) {
                t = idx[j];
                idx[j] = idx[j + 1];
                idx[j + 1] = t;
            }
        }
    }
    for (i = 1; i <= n; i++) {
        total += (long long)a[idx[i]] * (long long)(n - i);
    }
    printf("minwait: %lld\n", total);
    printf("order:");
    for (i = 1; i <= n; i++) {
        printf(" %d", idx[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

#define MAXS 10005
#define MAXN 15
#define INF 100000000

int main(void)
{
    int n, s, i, j;
    int a[MAXN];
    int dp[MAXS];

    if (scanf("%d%d", &n, &s) != 2) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (j = 0; j <= s; j++) {
        dp[j] = INF;
    }
    dp[0] = 0;
    for (i = 0; i < n; i++) {
        for (j = a[i]; j <= s; j++) {
            if (dp[j - a[i]] + 1 < dp[j]) {
                dp[j] = dp[j - a[i]] + 1;
            }
        }
    }
    if (dp[s] >= INF) {
        printf("impossible\n");
    } else {
        printf("min coupons: %d\n", dp[s]);
    }
    return 0;
}

#include <stdio.h>

#define MAXN 1005
#define MAXK 1005

int main(void)
{
    int n, k, i, j;
    int arrive[MAXN], serve[MAXN], wait[MAXN];
    int freeAt[MAXK];
    long long total = 0;
    int worst = 0;

    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }
    if (n > MAXN || k > MAXK) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        if (scanf("%d %d", &arrive[i], &serve[i]) != 2) {
            return 0;
        }
    }
    for (j = 0; j < k; j++) {
        freeAt[j] = 0;
    }
    for (i = 0; i < n; i++) {
        int best = 0;
        int start;
        /* 找一个最早空闲的窗口 */
        for (j = 1; j < k; j++) {
            if (freeAt[j] < freeAt[best]) {
                best = j;
            }
        }
        start = freeAt[best];
        if (start < arrive[i]) {
            start = arrive[i];      /* 人还没到，窗口只能等他 */
        }
        wait[i] = start - arrive[i];
        freeAt[best] = start + serve[i];
        total += wait[i];
        if (wait[i] > wait[worst]) {
            worst = i;
        }
    }
    for (i = 0; i < n; i++) {
        printf(i == 0 ? "%d" : " %d", wait[i]);
    }
    printf("\n");
    printf("%lld %d\n", total, worst + 1);
    return 0;
}

#include <stdio.h>

#define MAXN 100005

int main(void)
{
    static int a[MAXN];
    int n, i;
    int cand = 0, cnt = 0, total = 0;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
        if (cnt == 0) {
            cand = a[i];
            cnt = 1;
        } else if (a[i] == cand) {
            cnt++;
        } else {
            cnt--;
        }
    }
    for (i = 0; i < n; i++) {
        if (a[i] == cand) {
            total++;
        }
    }
    printf("%d %d\n", cand, total);
    return 0;
}

#include <stdio.h>

#define MAXN 2005

int main(void)
{
    static int t[MAXN], ans[MAXN], st[MAXN];
    int n, i, top = 0;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    for (i = 0; i < n; i++) {
        if (scanf("%d", &t[i]) != 1) {
            return 0;
        }
        ans[i] = 0;
    }
    /* 从右往左扫描，栈中保存下标，对应气温自栈底到栈顶递减 */
    for (i = n - 1; i >= 0; i--) {
        while (top > 0 && t[st[top - 1]] <= t[i]) {
            top--;
        }
        if (top > 0) {
            ans[i] = st[top - 1] - i;
        }
        st[top++] = i;
    }
    for (i = 0; i < n; i++) {
        printf(i == 0 ? "%d" : " %d", ans[i]);
    }
    printf("\n");
    return 0;
}

